const workerCapacity = 3;
for (let round = 1; round <= 4; round++) {
  waiting += arrivals;
  const finished = Math.min(waiting, workerCapacity);
  waiting -= finished;
  console.log(`round ${round}: ${waiting} waiting`);
}

const base = 100;
const cap = 1000;
const sampleJitter = [20, 5, 30];
for (let retry = 0; retry < sampleJitter.length; retry++) {
  const delay = Math.min(cap, base * 2 ** retry + sampleJitter[retry]);
  console.log(`retry ${retry + 1}: wait ${delay} ms`);
}

let state = "closed";
let failures = 0;
function result(ok) {
  if (state === "open") return "blocked";
  if (ok) {
    failures = 0;
    state = "closed";
  } else {
    failures++;
    if (state === "half-open" || failures >= 2) state = "open";
  }
  return state;
}
console.log(result(false));
console.log(result(false));
console.log(result(true));
state = "half-open"; // pretend the cooldown has passed
console.log(state);
console.log(result(true));

const requests = [0, 10, 20, 30, 60];
const limit = 3;
const windowSeconds = 60;
let accepted = [];
for (const now of requests) {
  accepted = accepted.filter(time => now - time < windowSeconds);
  if (accepted.length < limit) {
    accepted.push(now);
    console.log(now + "s allow");
  } else {
    console.log(now + "s wait");
  }
}

